// Validación de seguridad
if (!items[0].json.content) {
  return [{ json: { error: "No hay contenido. Verifica la URL de la API." } }];
}

const content = items[0].json.content;

// --- ESTRATEGIA NUEVA: BLOQUES MAESTROS ---
// 1. Buscamos el encabezado que define el inicio de una HU.
// Estructura: "### Nro. HU03 - Título: Publicar oferta"
// Capturamos:
// - Grupo 1: El Número (03)
// - Grupo 2: El Título (Publicar oferta)
// - Grupo 3: TODO el contenido hasta que empiece la siguiente HU o termine el archivo
const masterRegex = /(?:###|##)\s*Nro\.\s*HU(\d+)\s*-\s*Título:\s*([^\n\r]+)([\s\S]*?)(?=(?:###|##)\s*Nro\.\s*HU|$)/gi;

let match;
const resultados = [];

while ((match = masterRegex.exec(content)) !== null) {
  const huNumero = match[1];
  const huTitulo = match[2].trim();
  const huCuerpo = match[3]; // Aquí dentro están la descripción, criterios, tareas, etc.

  // 2. BUSCAR CRITERIOS (Solo dentro del cuerpo de ESTA HU)
  // Usamos un regex similar al tuyo, pero aplicado solo a 'huCuerpo'
  const criteriaRegex = /(?:#+\s*)?Criterios de aceptación\s*HU\d+([\s\S]*?)(?=(?:#+\s*)?Tareas|Nro\.\s*HU|(?:#+\s*)?Resumen|$)/i;

  const criteriaMatch = criteriaRegex.exec(huCuerpo);

  if (criteriaMatch) {
    let tablaRaw = criteriaMatch[1];

    // --- LIMPIEZA DE TEXTO (Tu lógica original) ---
    let textoLimpio = tablaRaw
      .replace(/Tareas\s*HU\d+/i, '')
      .replace(/Resumen\s*de\s*Story\s*Points/i, '')
      .replace(/\|?\s*:?-+:?\s*\|\s*:?-+:?\s*\|?/g, '') 
      .replace(/\*\*/g, '')
      .replace(/<br\s*\/?>/gi, ' ')
      .replace(/\|/g, ' - ')
      .replace(/Escenario\s*-\s*Descripción/gi, '')
      .replace(/\s+/g, ' ')
      .trim();

    // Solo guardamos si hay contenido real
    if (textoLimpio.length > 5) {
      resultados.push({
        json: {
          id: `HU-${huNumero}`,
          titulo: huTitulo, // <--- ¡AQUÍ ESTÁ TU TÍTULO!
          tipo: 'Entrenamiento',
          contenido_criterios: textoLimpio    
        }
      });
    }
  }
}

if (resultados.length === 0) {
    return [{ json: { warning: "No se encontraron HUs con el formato esperado." } }];
}

return resultados;

// Validamos que haya items
if (items.length === 0) {
    return [{ json: { contexto_entrenamiento: "No hay ejemplos históricos." } }];
}

// Recorremos cada item para darle formato individual
const listaEjemplos = items.map(item => {
    const datos = item.json;

    // Construimos el bloque con ID, TÍTULO y CRITERIOS
    // Nota: Es vital que 'datos.titulo' venga del nodo anterior.
    return `### EJEMPLO DE REFERENCIA (${datos.id})
TÍTULO: ${datos.titulo}
--------------------------------------------------
CRITERIOS:
${datos.contenido_criterios}`;
});

// AQUÍ ESTÁ LA CLAVE: Separamos cada bloque con una barrera visual GRANDE
// Usamos saltos de línea triples (\n\n\n) y una línea divisoria fuerte.
const separador = '\n\n\n--------------------------------------------------------------------------------\n\n\n';

const textoFinal = listaEjemplos.join(separador);

// Devolvemos el paquete listo para inyectar en el Merge Multiplex
return [{
    json: {

        contexto_entrenamiento: textoFinal
    }
}];

// 1. Recolectamos el texto con una extracción más robusta
const listaEscenarios = items.map(item => {
  const json = item.json;

  // CASO A: Estructura compleja de Gemini (según tu captura image_b2c14c.png)
  // content -> parts -> [0] -> text
  if (json.content && json.content.parts && json.content.parts[0] && json.content.parts[0].text) {
    return json.content.parts[0].text;
  }

  // CASO B: Estructura simple (si viene directo)
  return json.text || json.output || json.content;
})
.filter(texto => texto) // Elimina nulos o undefined
.map(texto => {
  // SEGURIDAD: Convertimos a String antes de hacer trim()
  // Esto evita el error si llega un número o un objeto por error
  return String(texto).trim(); 
});

// 2. Unimos todo con un separador Markdown claro
const contenidoUnido = listaEscenarios.join('\n\n---\n\n');

// 3. Creamos el documento final con encabezado y fecha
const fecha = new Date().toLocaleDateString('es-ES');
const documentoFinal = `# Reporte de Escenarios Generados (S1)\n> Generado el: ${fecha}\n\n${contenidoUnido}`;

// 4. Devolvemos el paquete para Azure DevOps
return [{
  json: {
    contenido_wiki: documentoFinal,
    page_path: "CriteriosS1", 
  }
}];

// 1. Obtenemos el contenido
const content = items[0].json.content;

if (!content) {
  return [{ json: { error: "El nodo HTTP no trajo contenido." } }];
}

// 2. ESTRATEGIA: DIVIDIR POR CABECERAS DE HU
const splitRegex = /(?:\n|^)(?=(?:#{1,6}\s*|[\*_]*)\s*(?:Nro\.?)?\s*HU\s*-?\s*\d+)/i;

const bloques = content.split(splitRegex);
const historias = [];

bloques.forEach(bloque => {
  const texto = bloque.trim();

  // A. EXTRAER ID Y TÍTULO
  const headerMatch = texto.match(/HU\s*-?\s*(\d+)[\s\S]*?Título\s*:?\s*([^\n\r]+)/i);

  if (headerMatch) {
    const idNum = headerMatch[1];
    const tituloLimpio = headerMatch[2].replace(/[\*_]/g, '').trim();

    // --- B. EXTRAER DESCRIPCIÓN ---
    let descripcion = "Descripción no detectada";
    // Actualizado para que se detenga antes de cualquier "Matriz" o "PASO"
    const descMatch = texto.match(/Descripción\s*:?\s*([\s\S]*?)(?=\s*####?\s*(?:PASO|Matriz))/i);

    if (descMatch) {
        descripcion = descMatch[1].trim();
    } else {
        const narrativaMatch = texto.match(/(COMO\s+[\s\S]+?QUIERO\s+[\s\S]+?PARA\s+[\s\S]+?)(?=\.|\||\n|####)/i);
        if (narrativaMatch) {
            descripcion = narrativaMatch[1].replace(/\|/g, '').trim(); 
        }
    }

    // --- C. EXTRAER TODAS LAS MATRICES (Incluso en múltiples pasos) ---
    // Atrapa desde "PASO" o "Matriz" hasta que se tope con un "GLOSARIO" o el fin del bloque
    const regexMatriz = /(?:####?\s*(?:PASO|Matriz))[\s\S]*?(?=(?:###\s*GLOSARIO|$))/gi;
    let matricesExtraidas = [];
    let matchM;
    while ((matchM = regexMatriz.exec(texto)) !== null) {
        matricesExtraidas.push(matchM[0].trim());
    }
    // Unimos todas las matrices encontradas (Paso 1, Paso 2, etc.)
    let matriz = matricesExtraidas.length > 0 ? matricesExtraidas.join("\n\n") : "Matriz no detectada";

    // --- D. EXTRAER TODOS LOS GLOSARIOS ---
    // Atrapa desde "GLOSARIO" hasta que se tope con otro "PASO" o "Matriz" o el fin del bloque
    const regexGlosario = /(?:###\s*GLOSARIO)[\s\S]*?(?=(?:####?\s*(?:PASO|Matriz)|$))/gi;
    let glosariosExtraidos = [];
    let matchG;
    while ((matchG = regexGlosario.exec(texto)) !== null) {
        glosariosExtraidos.push(matchG[0].trim());
    }
    // Unimos todos los glosarios encontrados
    let glosario = glosariosExtraidos.length > 0 ? glosariosExtraidos.join("\n\n") : "Glosario no detectado";

    // Guardamos el objeto completo
    historias.push({
      json: {
        id_hu: `HU-${idNum}`,
        titulo: tituloLimpio,
        descripcion: descripcion,
        tabla_decision_generada: matriz, 
        glosario_acciones: glosario      
      }
    });
  }
});

// 3. RESULTADO
if (historias.length === 0) {
    return [{ 
        json: { 
            warning: "No se detectaron historias con el formato esperado.",
            texto_inicio: content.substring(0, 500) 
        } 
    }];
}

return historias;

const itemsProcesados = [];

// Recorremos los items que vienen de "Code in JavaScript9"
for (const item of items) {
  const data = item.json;

  // Verificamos si existe el nombre del frame
  if (data.nombre_frame && data.nombre_frame.trim() !== "") {
    itemsProcesados.push({
      json: {
        id_hu: data.id_hu, // Usamos id_hu que es lo que viene en el input
        nombre_imagen_buscar: data.nombre_frame.trim() // Limpiamos espacios
      }
    });
  }
}

// Si no hay nada, n8n se detiene, por eso es bueno devolver al menos un aviso
if (itemsProcesados.length === 0) {
    return [{ json: { warning: "No se encontraron frames en la entrada." } }];
}

return itemsProcesados;

// 1. Obtenemos TODOS los datos de texto
const datosTexto = $('Code in JavaScript6').all();

const itemsFinales = [];

// --- MAPA DE AGRUPACIÓN (Igual que antes) ---
const mapaHUs = new Map();

datosTexto.forEach(item => {
  const data = item.json;
  if (data.nombre_imagen_buscar) {
    const nombreLimpio = data.nombre_imagen_buscar.trim();
    if (!mapaHUs.has(nombreLimpio)) {
      mapaHUs.set(nombreLimpio, []);
    }
    mapaHUs.get(nombreLimpio).push(data);
  }
});

// --- NUEVO: CONTROL DE DUPLICADOS ---
// Usamos esto para anotar qué imágenes ya "atendimos"
const imagenesProcesadas = new Set();

// 2. Recorremos las imágenes de Drive
for (const itemImagen of items) {
  const driveData = itemImagen.json; 
  const binaryData = itemImagen.binary;

  // Limpieza del nombre
  const nombreArchivoSinExt = driveData.name.replace(/\.[^/.]+$/, "").trim();

  // --- FILTRO ANTI-REPETICIÓN ---
  // Si ya procesamos una imagen con este nombre, saltamos a la siguiente.
  if (imagenesProcesadas.has(nombreArchivoSinExt)) {
    continue; 
  }

  // Si es nueva, la buscamos en el mapa
  const listaHUsCoincidentes = mapaHUs.get(nombreArchivoSinExt);

  if (listaHUsCoincidentes && listaHUsCoincidentes.length > 0) {

    // Marcamos esta imagen como "YA USADA" para que no se repita
    imagenesProcesadas.add(nombreArchivoSinExt);

    // Generamos los items (HU-13, HU-14, etc.)
    for (const huData of listaHUsCoincidentes) {
      itemsFinales.push({
        json: {
          id_hu: huData.id_hu,
          titulo: huData.titulo_hu,
          descripcion: huData.descripcion,
          observaciones: huData.observaciones,

          archivo_nombre_original: driveData.name,
          archivo_id: driveData.id
        },
        binary: binaryData
      });
    }
  }
}

return itemsFinales;

const grupos = {};

// 1. Recorremos todos los items sueltos
for (const item of items) {
  const json = item.json;

  // N8N maneja los binarios de forma particular. 
  // A veces viene como 'data', a veces como el nombre del archivo. 
  // Asumiremos que viene en la propiedad por defecto que suele ser 'data' o la primera llave disponible.
  const binaryKey = Object.keys(item.binary)[0]; 
  const binary = item.binary[binaryKey];

  const idHu = json.id_hu;

  // 2. Si es la primera vez que vemos esta HU, la inicializamos
  if (!grupos[idHu]) {
    grupos[idHu] = {
      json: {
        id_hu: idHu,
        titulo: json.titulo,
        descripcion: json.descripcion,
        observaciones: json.observaciones,
        // Inicializamos el array
        frames_info: [] 
      },
      binary: {}
    };
  }

  // 3. CORRECCIÓN AQUÍ: Usamos los nombres correctos que vienen del nodo anterior
  grupos[idHu].json.frames_info.push({
    // Antes tenías json.nombre_frame (incorrecto)
    nombre: json.archivo_nombre_original, 
    // Antes tenías json.archivo_drive_id (incorrecto)
    archivo_id: json.archivo_id        
  });

  // 4. Guardamos la imagen binaria con un nombre único para que no se sobrescriban
  const indice = Object.keys(grupos[idHu].binary).length;

  // Esto crea propiedades: data_0, data_1, data_2...
  grupos[idHu].binary[`data_${indice}`] = binary;
}

// 5. Devolvemos el array limpio
return Object.values(grupos);

// 1. Obtenemos el contenido
const content = items[0].json.content;

if (!content) {
  return [{ json: { error: "El nodo HTTP no trajo contenido." } }];
}

// 2. ESTRATEGIA FLEXIBLE: DIVIDIR POR CABECERAS DE HU
const splitRegex = /(?:\n|^)(?=(?:#{1,6}\s*|[\*_]*)\s*(?:Nro\.?)?\s*HU\s*-?\s*\d+)/i;
const bloques = content.split(splitRegex);
const output = [];

bloques.forEach(bloque => {
  const texto = bloque.trim();

  // A. EXTRAER EL ID
  const headerMatch = texto.match(/HU\s*-?\s*(\d+)/i);

  if (headerMatch) {
    const idNum = `HU-${headerMatch[1]}`;

    // B. BUSCAR SECCIÓN DE FRAMES
    const sectionFramesMatch = texto.match(/(?:Frame|Prototipo)[\s\S]*?(?=(?:Observaciones|Nota|###|$))/i);

    if (sectionFramesMatch) {
      const lineasFrames = sectionFramesMatch[0].split('\n');

      lineasFrames.forEach(linea => {
        // Detecta líneas que empiezan con viñetas (*, -, v, etc.)
        if (linea.match(/^\s*[-*+v]\.?\s*/i)) {
          const nombreLimpio = linea.replace(/^\s*[-*+vV\.0-9]*\s*/, '').trim();

          if (nombreLimpio.length > 0 && nombreLimpio.toLowerCase() !== "empty") {
            // IMPORTANTE: Creamos un item por cada frame con el ID de la HU
            output.push({
              json: {
                id_hu: idNum,
                nombre_frame: nombreLimpio,
                // Mantenemos una copia de la data original si la necesitas luego
                busqueda_drive: nombreLimpio 
              }
            });
          }
        }
      });
    }
  }
});

// 3. RESULTADO
if (output.length === 0) {
    return [{ json: { warning: "No se detectaron frames." } }];
}

return output;
